/**
 * Formatadores das telas de Operações.
 *
 * `BRL` reaproveita `formatCurrency` e as datas usam `dateFormater`, ambos de
 * `@/functions/formaters`. Os demais ficam aqui porque o equivalente do repo
 * entrega outro formato: `formatCompactCurrency` usa sufixo `M`/`k` em vez do
 * `mi`/`mil` pt-BR, e `formatNumberToPercentage` tem
 * `maximumSignificantDigits: 4`, que anula o `minimumFractionDigits: 2` e faz
 * "12,50%" sair como "12,5%" — o que quebra o alinhamento das colunas
 * `tabular-nums` destas telas.
 */

import { formatCurrency } from '@/functions/formaters/formatCurrency';

/** R$ 1.234,56 */
export const BRL = (n: number): string => formatCurrency(n);

/** R$ 1.235 — sem centavos, para tabelas densas. */
export const BRLc = (n: number): string =>
    'R$ ' + n.toLocaleString('pt-BR', { maximumFractionDigits: 0 });

/**
 * R$ 1,85 mi · R$ 890 mil · R$ 640 — versão curta para rankings e degraus,
 * onde o valor cheio estoura a coluna. `formatCompactCurrency` do repo não
 * serve aqui: usa sufixo `M`/`k` e ponto decimal, fora do padrão pt-BR.
 */
export const BRLcompacto = (n: number): string => {
    const abs = Math.abs(n);
    if (abs >= 1e6) {
        return (
            'R$ ' +
            (n / 1e6).toLocaleString('pt-BR', {
                minimumFractionDigits: 2,
                maximumFractionDigits: 2,
            }) +
            ' mi'
        );
    }
    if (abs >= 1e3) {
        return 'R$ ' + (n / 1e3).toLocaleString('pt-BR', { maximumFractionDigits: 0 }) + ' mil';
    }
    return BRLc(n);
};

/** R$ 5,6 mi */
export const MI = (n: number): string =>
    'R$ ' +
    (n / 1e6).toLocaleString('pt-BR', {
        minimumFractionDigits: 1,
        maximumFractionDigits: 1,
    }) +
    ' mi';

/** 5,6 mi — sem o prefixo, para eixos de gráfico. */
export const MIc = (n: number): string =>
    (n / 1e6).toLocaleString('pt-BR', {
        minimumFractionDigits: 1,
        maximumFractionDigits: 1,
    }) + ' mi';

/** Recebe o percentual já em base 100: `PCT(12.5)` → "12,50%". */
export const PCT = (n: number): string =>
    (Number.isFinite(n) ? n : 0).toLocaleString('pt-BR', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    }) + '%';

