    }

    const kpisMes: Indicador[] = [
        {
            id: 'desembolso',
            rotulo: 'Desembolso do mês',
            valor: BRL(kpis.desembolso),
            dica: `${kpis.qtd} ${kpis.qtd === 1 ? 'cessão fechada' : 'cessões fechadas'}`,
            icone: <Wallet className="size-4" aria-hidden />,
            cor: COLORS.success,
            destaque: true,
        },
        {
            id: 'liquido',
            rotulo: 'Líquido negociado',
            valor: BRL(kpis.vl),
            dica: 'valor de face declarado',
            icone: <Coins className="size-4" aria-hidden />,
            cor: COLORS.brand,
        },
        {
            id: 'ritmo',
            rotulo: 'Ritmo',
            valor: BRLc(ritmo.porDia),
            dica: ritmo.emCurso
                ? `por dia · dia ${ritmo.diaCorrente} de ${ritmo.diasNoMes}`
                : `por dia · mês fechado em ${ritmo.diasNoMes} dias`,
            icone: <Gauge className="size-4" aria-hidden />,
            cor: COLORS.brandDeep,
        },
        {
            id: 'ticket',
            rotulo: 'Ticket médio',
            valor: BRLc(kpis.ticket),
            dica: 'desembolso por cessão',
            icone: <Receipt className="size-4" aria-hidden />,
            cor: COLORS.warning,
        },
    ];

    const kpisHist: Indicador[] = [
        {
            id: 'periodo',
            rotulo: 'Desembolso no período',
            valor: MI(somaSerie),
            dica: `${serie.length} meses`,
            icone: <Wallet className="size-4" aria-hidden />,
            cor: COLORS.brand,
            destaque: true,
        },
        {
            id: 'media',
            rotulo: 'Média mensal',
            valor: MI(mediaFechados),
            dica: `${fechados.length} meses fechados`,
            icone: <TrendingUp className="size-4" aria-hidden />,
            cor: COLORS.brandDeep,
        },
        {
            id: 'cessoes',
            rotulo: 'Cessões',
            valor: String(somaOps),
            dica: somaOps ? `ticket médio ${BRLc(somaSerie / somaOps)}` : 'sem cessões no período',
            icone: <FileText className="size-4" aria-hidden />,
            cor: COLORS.success,
        },
        {
            id: 'melhor',
            rotulo: 'Melhor mês fechado',
            valor: melhor ? MIc(melhor.desembolso) : '—',
            dica: melhor ? melhor.rotulo : 'sem meses fechados na série',
            icone: <Target className="size-4" aria-hidden />,
            cor: COLORS.warning,
        },
    ];

    return (
        <div className="flex min-w-0 flex-col gap-4 sm:gap-5 md:gap-6">
            <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex flex-wrap items-center gap-3">
                    <div
                        className="flex items-center gap-1 rounded-xl border p-1"
                        role="group"
                        aria-label="Mês de referência"
                        style={{ borderColor: COLORS.line, background: withAlpha(COLORS.card, 0.5) }}
                    >
                        <Button
                            type="button"
                            variant="ghost"
                            onClick={() => irParaMes(-1)}
                            disabled={trocandoMes}
                            aria-label="Mês anterior"
                            className={cn(
                                botaoCompactoClass,
                                'size-7 px-0',
                                trocandoMes && 'opacity-40',
                            )}
                        >
                            <ChevronLeft size={14} aria-hidden />
                        </Button>
                        <span
                            className="flex min-w-40 items-center justify-center gap-1.5 text-center font-satoshi text-[13px] font-bold capitalize"
                            style={{ color: COLORS.text }}
                            aria-busy={trocandoMes}
                        >
                            {trocandoMes ? (
                                <LoaderCircle
                                    className="size-3.5 shrink-0 animate-spin motion-reduce:animate-none"
                                    style={{ color: COLORS.brand }}
                                    aria-hidden
                                />
                            ) : null}
                            {nomeDoMes(mesExibido.ano, mesExibido.mes)}
                        </span>
                        <Button
                            type="button"
                            variant="ghost"
                            onClick={() => irParaMes(1)}
                            disabled={trocandoMes || ehMesCorrente(mesExibido.ano, mesExibido.mes)}
                            aria-label="Próximo mês"
                            className={cn(
                                botaoCompactoClass,
                                'size-7 px-0',
                                (trocandoMes || ehMesCorrente(mesExibido.ano, mesExibido.mes)) &&
                                    'opacity-40',
                            )}
                        >
                            <ChevronRight size={14} aria-hidden />
                        </Button>
                    </div>

                    <p className={TYPOGRAPHY.hint} style={{ color: COLORS.textDim }}>
                        {modo === 'mes'
                            ? 'Desembolso da equipe contra as três metas do mês'
                            : `Comparativo mensal · ${serie[0]?.rotulo ?? '—'} a ${rotuloDoMes(ano, mes)}`}
                        {isFetching && !isPlaceholderData ? ' · atualizando…' : ''}
                    </p>
                </div>

                <PilulaSegmentada
                    aria-label="Período do painel"
                    valor={modo}
                    opcoes={MODOS}
                    onChange={trocarModo}
                />
            </div>

            {modo === 'mes' ? (
                <div className="relative flex min-w-0 flex-col gap-4 sm:gap-5 md:gap-6">
                    {trocandoMes ? (
                        <VeuCarregando
                            mensagem={`Carregando ${nomeDoMes(mesExibido.ano, mesExibido.mes)}…`}
                        />
                    ) : null}

                    <GradeIndicadores
                        aria-label="Indicadores do mês corrente"
                        indicadores={kpisMes}
                    />

                    <div className="grid gap-4 sm:gap-5 md:gap-6 lg:grid-cols-[minmax(0,1fr)_420px]">
                        <Cartao className="flex flex-col">
                            <CabecalhoCartao
                                rotulo="Status de metas coletivas"
                                titulo={`Progressão de ${nomeDoMes(ano, mes)}`}
                                legenda="base: desembolso"
                            />

                            {temMetas ? (
                                <>
                                    <Poco className="mt-5 p-4 sm:p-5">
                                        <div className="grid grid-cols-[72px_1fr] items-end gap-5 sm:grid-cols-[92px_1fr] sm:gap-6">
                                            <ColunaProgresso
                                                aria-label="Progresso do desembolso contra as metas coletivas"
                                                emCarga
                                                preenchido={(escada.desembolso / escada.teto) * 100}
                                                marcas={escada.metas.map((meta) => ({
                                                    n: meta.rotulo,
                                                    pct: (meta.valor / escada.teto) * 100,
                                                }))}
                                            />

                                            <div className="flex h-80 flex-col justify-between">
                                                {[2, 1, 0].map((i) => {
                                                    const meta = escada.metas[i];
                                                    const ok =
                                                        meta.valor > 0 &&
                                                        escada.desembolso >= meta.valor;
                                                    return (
                                                        <DegrauMeta
                                                            key={meta.rotulo}
                                                            ordem={i + 1}
                                                            titulo={`${meta.rotulo} · ${MIc(meta.valor)}`}
                                                            detalhe={
                                                                meta.valor === 0
                                                                    ? 'sem meta cadastrada'
                                                                    : ok
                                                                      ? 'conquistada'
                                                                      : `faltam ${BRLc(meta.valor - escada.desembolso)}`
                                                            }
                                                            valor={
                                                                meta.valor > 0
                                                                    ? `${Math.min(100, Math.round((escada.desembolso / meta.valor) * 100))}%`
                                                                    : '—'
                                                            }
                                                            legendaValor={ok ? undefined : 'do alvo'}
                                                            atingida={ok}
                                                            proxima={
                                                                !ok && i === escada.proximaMeta
                                                            }
                                                        />
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    </Poco>

                                    <FaixaDestaque
                                        className="mt-4"
                                        cor={proxima ? COLORS.warning : COLORS.success}
                                        Icone={proxima ? Target : Trophy}
                                        principal={
                                            proxima ? (
                                                <>
                                                    <b
                                                        className="font-bold tabular-nums"
                                                        style={{ fontFamily: FONT_DATA }}
                                                    >
                                                        Faltam{' '}
                                                        {BRL(proxima.valor - escada.desembolso)}
                                                    </b>{' '}
                                                    para a {proxima.rotulo}.
                                                </>
                                            ) : (
                                                <>Todas as metas do mês foram batidas.</>
                                            )
                                        }
                                        acessorio={
                                            proxima && diaDaProxima ? (
                                                <span
                                                    className="font-satoshi text-sm font-bold"
                                                    style={{ color: COLORS.warning }}
                                                >
                                                    chega no dia {diaDaProxima}/
                                                    {String(mes).padStart(2, '0')} no ritmo atual
                                                </span>
                                            ) : undefined
                                        }
                                    />
                                </>
                            ) : (
                                <Poco className="mt-5 p-5">
                                    <p
                                        className="font-satoshi text-sm"
                                        style={{ color: COLORS.textDim }}
                                    >
                                        Nenhuma meta cadastrada para {nomeDoMes(ano, mes)}. O
                                        desembolso do mês está em{' '}
                                        <b style={{ color: COLORS.text }}>
                                            {BRL(escada.desembolso)}
                                        </b>
                                        .
                                    </p>
                                </Poco>
                            )}
                        </Cartao>

                        {rankMes.length ? (
                            <Podio
                                rank={rankMes}
                                rotulo="Ranking do mês"
                                titulo={`Pódio de ${nomeDoMes(ano, mes)}`}
                                legenda={`${kpis.qtd} cessões no mês`}
                                nota="Acumulado do mês corrente, por desembolso."
                            />
                        ) : (
                            <Cartao>
                                <CabecalhoCartao
                                    rotulo="Ranking do mês"
                                    titulo="Sem pódio neste mês"
                                    legenda="nenhuma cessão fechada"
                                />
                            </Cartao>
                        )}
                    </div>

                    <Cartao>
                        <CabecalhoCartao
                            rotulo="Movimento do mês"
                            titulo={`Cessões de ${nomeDoMes(ano, mes)}`}
                            legenda={
                                ativos
                                    ? `${operacoes?.count ?? 0} de ${kpis.qtd} no filtro · página ${operacoes?.page ?? 1} de ${paginas}`
                                    : `${operacoes?.count ?? 0} no mês · página ${operacoes?.page ?? 1} de ${paginas}`
                            }
                        />

                        <FiltrosOperacoes
                            filtros={filtros}
                            onFiltro={definirFiltro}
                            onLimpar={limparFiltros}
                            ativos={ativos}
                        />

                        <div className="relative">
                            {carregandoTabela ? (
                                <VeuCarregando mensagem="Carregando cessões…" />
                            ) : null}

                            {linhas.length === 0 ? (
                                <p
                                    className={cn('mt-4 block min-h-16', TYPOGRAPHY.hint)}
                                    style={{ color: COLORS.textDim }}
                                >
                                    {ativos
                                        ? 'Nenhuma cessão do mês casa com os filtros.'
                                        : 'Nenhuma cessão fechada neste mês.'}
                                </p>
                            ) : (
                                <>
                                        <MolduraTabela className="mt-4">
                                        <Table className="w-full border-collapse">
                                            <TableHeader style={theadSuaveStyle} className={theadSuaveClass}>
                                                <TableRow>
                                                    {[
                                                        'Data',
                                                        'Closer',
                                                        'Ente devedor',
                                                        'Cedente',
                                                        'Esfera',
                                                    ].map((h) => (
                                                        <TableHead key={h} className={cn(thSuaveClass, 'h-auto')}>
                                                            {h}
                                                        </TableHead>
                                                    ))}
                                                    <TableHead className={cn(thSuaveClass, 'h-auto text-right')}>
                                                        Valor líquido
                                                    </TableHead>
                                                    <TableHead className={cn(thSuaveClass, 'h-auto text-right')}>
                                                        Desembolso
                                                    </TableHead>
                                                    {podeTirarDaParede ? (
                                                        <TableHead className={cn(thSuaveClass, 'h-auto text-right')}>
                                                            Ligações
                                                        </TableHead>
                                                    ) : null}
                                                    {podeTirarDaParede ? (
                                                        <TableHead
                                                            className={cn(
                                                                thSuaveClass,
                                                                'h-auto text-right',
                                                            )}
                                                        >
                                                            Ações
                                                        </TableHead>
                                                    ) : null}
                                                </TableRow>
                                            </TableHeader>
                                            <TableBody>
                                                {linhas.map((o, i) => {
                                                    const esfera = rotuloEsfera(o.esfera);
                                                    return (
                                                        <TableRow
                                                            key={
                                                                o.operacao_financeira_id ??
                                                                `${o.data}-${o.closer_id}-${i}`
                                                            }
                                                            className={cn(
                                                                'border-b-0 hover:bg-transparent',
                                                                linhaSuaveClass,
                                                            )}
                                                            style={{
                                                                ...divisoriaLinhaStyle,
                                                                ...(o.data === hoje
                                                                    ? {
                                                                          background: withAlpha(
                                                                              COLORS.success,
                                                                              0.07,
                                                                          ),
                                                                      }
                                                                    : null),
                                                            }}
                                                        >
                                                            <TableCell
                                                                className={cn(
                                                                    tdSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                                style={{
                                                                    color: COLORS.text,
                                                                    fontFamily: FONT_DATA,
                                                                }}
                                                            >
                                                                {o.data ? dateFormater(o.data) : '—'}
                                                            </TableCell>
                                                            <TableCell
                                                                className={cn(
                                                                    tdSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                                style={{ color: COLORS.text }}
                                                            >
                                                                <span
                                                                    className="mr-2.5 inline-grid size-7 place-items-center rounded-full align-middle font-satoshi text-[11px] font-bold text-white"
                                                                    style={{
                                                                        background: corDoCloser(
                                                                            o.closer_id ?? 0,
                                                                        ),
                                                                    }}
                                                                    aria-hidden
                                                                >
                                                                    {getInitials(o.closer ?? '?')}
                                                                </span>
                                                                {o.closer ??
                                                                    CLOSER_NAO_IDENTIFICADO_ROTULO}
                                                            </TableCell>
                                                            <TableCell
                                                                className={cn(
                                                                    tdSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                                style={{ color: COLORS.text }}
                                                            >
                                                                {o.ente_devedor ?? '—'}
                                                            </TableCell>
                                                            <TableCell
                                                                className={cn(
                                                                    tdSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                                style={{ color: COLORS.text }}
                                                            >
                                                                {o.cedente ?? '—'}
                                                            </TableCell>
                                                            <TableCell
                                                                className={cn(
                                                                    tdSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                            >
                                                                {o.esfera ? (
                                                                    <Selo
                                                                        cor={
                                                                            COR_ESFERA[esfera] ??
                                                                            COLORS.textDim
                                                                        }
                                                                        className={seloPilulaClass}
                                                                    >
                                                                        {esfera}
                                                                    </Selo>
                                                                ) : (
                                                                    '—'
                                                                )}
                                                            </TableCell>
                                                            <TableCell
                                                                className={cn(
                                                                    tdDadoSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                                style={{
                                                                    color: COLORS.text,
                                                                    fontFamily: FONT_DATA,
                                                                }}
                                                            >
                                                                {BRLc(parseMoneyValue(o.vl))}
                                                            </TableCell>
                                                            <TableCell
                                                                className={cn(
                                                                    tdDadoSuaveClass,
                                                                    'whitespace-nowrap',
                                                                )}
                                                                style={{
                                                                    color: COLORS.text,
                                                                    fontFamily: FONT_DATA,
                                                                }}
                                                            >
                                                                {BRL(parseMoneyValue(o.desembolso))}
                                                            </TableCell>
                                                            {podeTirarDaParede ? (
                                                                <TableCell
                                                                    className={cn(
                                                                        tdSuaveClass,
                                                                        'text-right',
                                                                    )}
                                                                >
                                                                    <LigacoesCessao
                                                                        posId={o.pos_id ?? null}
                                                                        operacaoFinanceiraId={
                                                                            o.operacao_financeira_id ??
                                                                            null
                                                                        }
                                                                    />
                                                                </TableCell>
                                                            ) : null}
                                                            {podeTirarDaParede ? (
                                                                <TableCell
                                                                    className={cn(
                                                                        tdSuaveClass,
                                                                        'text-right',
                                                                    )}
                                                                >
                                                                    <AcoesDaParede
                                                                        linha={o}
                                                                        travado={saidaTravada}
                                                                        onPedir={setSaidaPedida}
                                                                    />
                                                                </TableCell>
                                                            ) : null}
                                                        </TableRow>
                                                    );
                                                })}
                                            </TableBody>
                                        </Table>
                                    </MolduraTabela>

                                    <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
                                        <span
                                            className={TYPOGRAPHY.hint}
                                            style={{ color: COLORS.textDim }}
                                        >
                                            Mostrando {linhas.length} de {operacoes?.count ?? 0} cessões
                                            {ativos ? ' filtradas' : ''}
                                        </span>
                                        <div className="flex items-center gap-2">
                                            <Button
                                                type="button"
                                                variant="ghost"
                                                onClick={() => setPagina((p) => Math.max(1, p - 1))}
                                                disabled={carregandoTabela || (operacoes?.page ?? 1) <= 1}
                                                className={cn(
                                                    botaoCompactoClass,
                                                    (carregandoTabela || (operacoes?.page ?? 1) <= 1) &&
                                                        'opacity-40',
                                                )}
                                            >
                                                Anterior
                                            </Button>
                                            <span
                                                className={TYPOGRAPHY.hint}
                                                style={{ color: COLORS.textDim }}
                                            >
                                                {operacoes?.page ?? 1} / {paginas}
                                            </span>
                                            <Button
                                                type="button"
                                                variant="ghost"
                                                onClick={() =>
                                                    setPagina((p) => Math.min(paginas, p + 1))
                                                }
                                                disabled={
                                                    carregandoTabela ||
                                                    (operacoes?.page ?? 1) >= paginas
                                                }
                                                className={cn(
                                                    botaoCompactoClass,
                                                    (carregandoTabela ||
                                                        (operacoes?.page ?? 1) >= paginas) &&
                                                        'opacity-40',
                                                )}
                                            >
                                                Próxima
                                            </Button>
                                        </div>
                                    </div>
                                </>
                            )}
                        </div>
                    </Cartao>
                </div>
            ) : (
                <div className="relative flex min-w-0 flex-col gap-4 sm:gap-5 md:gap-6">
                    {trocandoMes ? (
                        <VeuCarregando
                            mensagem={`Carregando ${nomeDoMes(mesExibido.ano, mesExibido.mes)}…`}
                        />
                    ) : null}

                    <GradeIndicadores aria-label="Indicadores do período" indicadores={kpisHist} />

                    <Cartao>
                        <CabecalhoCartao
                            rotulo="Série histórica"
                            titulo="Desembolso mês a mês"
                            legenda={`${serie.length} meses até ${rotuloDoMes(ano, mes)}`}
                        />
                        <Poco className="mt-4 p-3 sm:p-4">
                            <GraficoHistorico serie={serie} metas={escada.metas} />
                        </Poco>
                    </Cartao>

                    <Cartao>
                        <CabecalhoCartao
                            rotulo="Fechamento"
                            titulo="Fechamento de cada mês"
                            legenda="variação sobre o mês anterior"
                        />
                        <MolduraTabela className="mt-4">
                            <Table className="w-full border-collapse">
                                <TableHeader style={theadSuaveStyle} className={theadSuaveClass}>
                                    <TableRow>
                                        <TableHead className={cn(thSuaveClass, 'h-auto')}>Mês</TableHead>
                                        {[
                                            'Desembolso',
                                            'Líquido',
                                            'Cessões',
                                            'Ticket médio',
                                            'Variação',
                                            'Faixa',
                                        ].map((h) => (
                                            <TableHead
                                                key={h}
                                                className={cn(thSuaveClass, 'h-auto text-right')}
                                            >
                                                {h}
                                            </TableHead>
                                        ))}
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {serie
                                        .slice()
                                        .reverse()
                                        .map((h) => (
                                            <TableRow
                                                key={`${h.ano}-${h.mes}`}
                                                className={cn(
                                                    'border-b-0 hover:bg-transparent',
                                                    linhaSuaveClass,
                                                )}
                                                style={{
                                                    ...divisoriaLinhaStyle,
                                                    ...(h.atual
                                                        ? {
                                                              background: withAlpha(
                                                                  COLORS.warning,
                                                                  0.09,
                                                              ),
                                                          }
                                                        : null),
                                                }}
                                            >
                                                <TableCell
                                                    className={cn(
                                                        tdSuaveClass,
                                                        'font-bold whitespace-nowrap',
                                                    )}
                                                    style={{ color: COLORS.text }}
                                                >
                                                    {h.rotulo}
                                                    {h.atual ? (
                                                        <span
                                                            className="ml-1 text-[11.5px] font-normal"
                                                            style={{ color: COLORS.textDim }}
                                                        >
                                                            · mês pedido
                                                        </span>
                                                    ) : null}
                                                </TableCell>
                                                {[
                                                    BRL(h.desembolso),
                                                    MI(h.vl),
                                                    String(h.qtd),
                                                    BRLc(h.ticket),
                                                ].map((v, k) => (
                                                    <TableCell
                                                        key={k}
                                                        className={cn(
                                                            tdDadoSuaveClass,
                                                            'whitespace-nowrap',
                                                        )}
                                                        style={{
                                                            color: COLORS.text,
                                                            fontFamily: FONT_DATA,
                                                        }}
                                                    >
                                                        {v}
                                                    </TableCell>
                                                ))}
                                                <TableCell
                                                    className={cn(
                                                        tdDadoSuaveClass,
                                                        'whitespace-nowrap',
                                                    )}
                                                    style={{
                                                        color: COLORS.text,
                                                        fontFamily: FONT_DATA,
                                                    }}
                                                >
                                                    {h.variacao == null ? (
                                                        '—'
                                                    ) : (
                                                        <span
                                                            style={{
                                                                color:
                                                                    h.variacao >= 0
                                                                        ? COLORS.success
                                                                        : COLORS.danger,
                                                            }}
                                                        >
                                                            {h.variacao >= 0 ? '▲' : '▼'}{' '}
                                                            {Math.abs(h.variacao).toFixed(1)}%
                                                        </span>
                                                    )}
                                                </TableCell>
                                                <TableCell
                                                    className={cn(
                                                        tdSuaveClass,
                                                        'text-right whitespace-nowrap',
                                                    )}
                                                >
                                                    <Selo
                                                        cor={
                                                            h.faixa === 'm1'
                                                                ? COLORS.textDim
                                                                : COLORS.success
                                                        }
                                                        className={cn(seloPilulaClass, 'ml-auto')}
                                                    >
                                                        {ROTULO_FAIXA[h.faixa] ?? h.faixa}
                                                    </Selo>
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                </TableBody>
                            </Table>
                        </MolduraTabela>
                        <p className={cn('mt-3', TYPOGRAPHY.hint)} style={{ color: COLORS.textDim }}>
                            A faixa é a que o mês fechou: 0 ou 1 meta batida cai na Faixa 1, duas na
                            Faixa 2, três na Faixa 3.
                        </p>
                    </Cartao>
                </div>
            )}

            {podeTirarDaParede ? (
                <SaidaDaParedeDialog
                    pedida={saidaPedida}
                    onOpenChange={(aberto) => {
                        if (!aberto && !saidaTravada) setSaidaPedida(null);
                    }}
                    onConfirm={confirmarSaida}
                    pendente={saidaTravada}
                />
            ) : null}
        </div>
    );
}
